<?php namespace App\Notifications; use App\Models\Reminder; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification; class ReminderDueNotification extends Notification { use Queueable; public function __construct(public Reminder $reminder){} public function via($notifiable):array{return ['database'];} public function toDatabase($notifiable):array{return ['title'=>$this->reminder->title,'type'=>$this->reminder->type,'pet_id'=>$this->reminder->pet_id,'due_at'=>$this->reminder->due_at?->toISOString()];} }